-- Phase 64: franchise finance is a specialized layer over Financial Management,
-- Network Governance, Contracts, Payments, Fiscal, Reporting and Data Platform.
-- quality: allow-nonconcurrent-index reason=new-empty-franchise-finance-tables

create schema if not exists franchise_finance_private;
revoke all on schema franchise_finance_private from public,anon,authenticated;

create table public.franchise_finance_member_permissions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permissions text[] not null default '{franchise_finance:view_own}',store_ids uuid[] not null default '{}',active boolean not null default true,updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),unique(organization_id,user_id));
create table public.franchise_financial_profiles(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,brand_id uuid references public.network_brands(id) on delete set null,region_id uuid references public.network_regions(id) on delete set null,franchisee_entity_id uuid not null references public.establishments(id) on delete restrict,contract_id uuid not null references public.contracts(id) on delete restrict,effective_from date not null,effective_until date,currency char(3) not null default 'BRL',status text not null default 'draft' check(status in('draft','active','suspended','expired','terminated')),billing_cycle text not null default 'monthly' check(billing_cycle in('monthly','quarterly','custom')),settlement_terms jsonb not null default '{}',owner_user_ids uuid[] not null default '{}',created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(effective_until is null or effective_until>=effective_from),unique(organization_id,franchisee_entity_id,contract_id,effective_from));
create table public.fee_basis_policies(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,metric_id text not null references public.analytics_metric_catalog(metric_key),included_components text[] not null default '{}',excluded_components text[] not null default '{}',excluded_channels text[] not null default '{}',excluded_product_categories uuid[] not null default '{}',rounding_policy text not null check(rounding_policy in('per_transaction','per_period','currency_standard')),timezone text not null,recognition_policy text not null,version integer not null default 1,effective_from date not null,effective_until date,created_by uuid references auth.users(id),created_at timestamptz not null default now(),check(effective_until is null or effective_until>=effective_from),unique(organization_id,metric_id,version));
create table public.franchise_fee_rules(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,financial_profile_id uuid references public.franchise_financial_profiles(id) on delete cascade,scope_type text not null default 'contract' check(scope_type in('organization','brand','region','store','contract')),scope_id uuid,fee_type text not null check(fee_type in('royalty','marketing_fund','advertising','technology','training','operations','campaign_contribution','fixed_fee','custom')),calculation_method text not null check(calculation_method in('fixed','percentage','fixed_plus_percentage','tiered_percentage','minimum_guarantee','custom_safe_formula')),basis_policy_id uuid references public.fee_basis_policies(id) on delete restrict,rate numeric(12,8),fixed_amount_cents bigint,minimum_amount_cents bigint,maximum_amount_cents bigint,safe_formula_key text,contract_id uuid references public.contracts(id) on delete restrict,effective_from date not null,effective_until date,version integer not null default 1,priority integer not null default 0,active boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz not null default now(),check(rate is null or rate>=0),check(fixed_amount_cents is null or fixed_amount_cents>=0),check(minimum_amount_cents is null or minimum_amount_cents>=0),check(maximum_amount_cents is null or maximum_amount_cents>=0),check(maximum_amount_cents is null or minimum_amount_cents is null or maximum_amount_cents>=minimum_amount_cents),check(effective_until is null or effective_until>=effective_from));
create table public.franchise_fee_rule_versions(id uuid primary key default gen_random_uuid(),rule_id uuid not null references public.franchise_fee_rules(id) on delete restrict,organization_id uuid not null references public.organizations(id) on delete cascade,version integer not null,rule_snapshot jsonb not null,effective_from date not null,effective_until date,calculation_hash text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(rule_id,version));
create table public.franchise_fee_tiers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,rule_id uuid not null references public.franchise_fee_rules(id) on delete cascade,from_value_cents bigint not null check(from_value_cents>=0),to_value_cents bigint,rate numeric(12,8) not null check(rate>=0),fixed_component_cents bigint check(fixed_component_cents is null or fixed_component_cents>=0),check(to_value_cents is null or to_value_cents>from_value_cents),unique(rule_id,from_value_cents));
create table public.franchise_fee_exemptions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,profile_id uuid not null references public.franchise_financial_profiles(id) on delete restrict,rule_id uuid references public.franchise_fee_rules(id) on delete restrict,start_date date not null,end_date date not null,exemption_type text not null check(exemption_type in('full','percentage','fixed_amount','grace_period')),percentage numeric(7,4),amount_cents bigint,reason text not null,approval_id uuid references public.internal_approvals(id) on delete restrict,reference_document_id uuid references public.compliance_documents(id) on delete restrict,status text not null default 'approved' check(status in('draft','pending_approval','approved','expired','cancelled')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),check(end_date>=start_date));
create table public.franchise_assessment_periods(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,profile_id uuid not null references public.franchise_financial_profiles(id) on delete restrict,period_start date not null,period_end date not null,status text not null default 'open' check(status in('open','calculating','review','approved','invoiced','settled','closed','disputed')),quality_status text not null default 'blocked' check(quality_status in('ready','warning','blocked')),quality_snapshot jsonb not null default '{}',calculation_hash text,calculated_at timestamptz,locked_at timestamptz,approved_at timestamptz,closed_at timestamptz,reopened_at timestamptz,reopen_reason text,version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(period_end>=period_start),unique(profile_id,period_start,period_end,version));
create table public.franchise_fee_assessments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,assessment_period_id uuid not null references public.franchise_assessment_periods(id) on delete restrict,fee_rule_id uuid not null references public.franchise_fee_rules(id) on delete restrict,basis_amount_cents bigint not null,rate numeric(12,8),calculated_amount_cents bigint not null,adjustment_amount_cents bigint not null default 0,final_amount_cents bigint not null,calculation_snapshot jsonb not null,calculation_hash text not null,status text not null default 'calculated' check(status in('calculated','review','approved','superseded','disputed')),created_at timestamptz not null default now(),unique(assessment_period_id,fee_rule_id,calculation_hash));
create table public.franchise_adjustments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,profile_id uuid not null references public.franchise_financial_profiles(id) on delete restrict,assessment_id uuid references public.franchise_fee_assessments(id) on delete restrict,adjustment_type text not null check(adjustment_type in('credit','debit','correction','discount','waiver','prior_period_adjustment','opening_balance')),amount_cents bigint not null check(amount_cents>0),reason text not null,reference_document_id uuid references public.compliance_documents(id) on delete restrict,approval_id uuid references public.internal_approvals(id) on delete restrict,created_by uuid references auth.users(id),approved_by uuid references auth.users(id),status text not null default 'pending' check(status in('pending','approved','rejected','applied','reversed')),created_at timestamptz not null default now(),approved_at timestamptz);
create table public.marketing_fund_accounts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,brand_id uuid references public.network_brands(id) on delete set null,region_id uuid references public.network_regions(id) on delete set null,name text not null,currency char(3) not null default 'BRL',allocation_scope text not null check(allocation_scope in('national','regional','local')),managerial_only boolean not null default true,active boolean not null default true,created_at timestamptz not null default now());
create table public.marketing_fund_contributions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,fund_id uuid not null references public.marketing_fund_accounts(id) on delete restrict,profile_id uuid not null references public.franchise_financial_profiles(id) on delete restrict,assessment_id uuid references public.franchise_fee_assessments(id) on delete restrict,amount_cents bigint not null check(amount_cents>=0),period_start date not null,period_end date not null,status text not null check(status in('assessed','due','paid','overdue','adjusted')),created_at timestamptz not null default now(),unique(fund_id,assessment_id));
create table public.marketing_fund_expense_links(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,fund_id uuid not null references public.marketing_fund_accounts(id) on delete restrict,financial_entry_id uuid not null references public.financial_entries(id) on delete restrict,campaign_id uuid,allocated_amount_cents bigint not null check(allocated_amount_cents>0),approval_id uuid references public.internal_approvals(id),created_at timestamptz not null default now(),unique(fund_id,financial_entry_id));
create table public.franchise_settlements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,profile_id uuid not null references public.franchise_financial_profiles(id) on delete restrict,assessment_period_id uuid not null references public.franchise_assessment_periods(id) on delete restrict,total_due_cents bigint not null,credits_cents bigint not null default 0,net_due_cents bigint not null,due_date date not null,status text not null default 'draft' check(status in('draft','issued','partially_paid','paid','overdue','disputed','cancelled')),collection_method text check(collection_method in('invoice','boleto_provider','pix','bank_transfer','manual_reconciliation','direct_debit_future')),payment_reference text,financial_entry_id uuid references public.financial_entries(id) on delete restrict,settled_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(assessment_period_id));
create table public.franchise_statements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,profile_id uuid not null references public.franchise_financial_profiles(id) on delete restrict,period_id uuid not null references public.franchise_assessment_periods(id) on delete restrict,version integer not null,generated_at timestamptz not null default now(),document_id uuid references public.compliance_documents(id) on delete restrict,report_export_id uuid,status text not null default 'generated' check(status in('draft','generated','issued','superseded')),snapshot jsonb not null,unique(profile_id,period_id,version));
create table public.franchise_financial_disputes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,profile_id uuid not null references public.franchise_financial_profiles(id) on delete restrict,assessment_id uuid references public.franchise_fee_assessments(id) on delete restrict,settlement_id uuid references public.franchise_settlements(id) on delete restrict,opened_by uuid not null references auth.users(id),reason text not null,status text not null default 'open' check(status in('open','under_review','resolved','rejected','withdrawn')),payment_policy text not null default 'payment_due_continues' check(payment_policy in('payment_due_continues','payment_paused','partial_hold')),support_ticket_id uuid,resolution text,opened_at timestamptz not null default now(),resolved_at timestamptz,check(assessment_id is not null or settlement_id is not null));
create table public.franchise_financial_ledger(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,profile_id uuid not null references public.franchise_financial_profiles(id) on delete restrict,entry_type text not null check(entry_type in('assessment','payment','credit','debit_adjustment','refund','waiver','carry_forward','opening_balance','reversal')),reference_type text not null,reference_id uuid,debit_cents bigint not null default 0,credit_cents bigint not null default 0,balance_effect_cents bigint generated always as (debit_cents-credit_cents) stored,reversal_of_id uuid references public.franchise_financial_ledger(id) on delete restrict,occurred_at timestamptz not null,period_start date not null,period_end date not null,metadata jsonb not null default '{}',idempotency_key text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),check((debit_cents>0 and credit_cents=0) or (credit_cents>0 and debit_cents=0)),unique(organization_id,idempotency_key));
create table public.franchise_reconciliation_issues(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,profile_id uuid not null references public.franchise_financial_profiles(id) on delete restrict,settlement_id uuid references public.franchise_settlements(id) on delete restrict,financial_reconciliation_id uuid references public.financial_reconciliations(id) on delete restrict,issue_type text not null check(issue_type in('payment_without_settlement','settlement_without_payment','underpayment','overpayment','duplicate_payment','unidentified_transfer')),expected_cents bigint,received_cents bigint,status text not null default 'open' check(status in('open','matched','resolved','dismissed')),resolution text,resolved_by uuid references auth.users(id),created_at timestamptz not null default now(),resolved_at timestamptz);
create table public.franchise_finance_jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,profile_id uuid references public.franchise_financial_profiles(id) on delete cascade,period_id uuid references public.franchise_assessment_periods(id) on delete cascade,job_type text not null check(job_type in('calculate_period','network_close','generate_statement','reconcile','forecast','export')),status text not null default 'pending' check(status in('pending','processing','retrying','completed','failed','dead_letter')),payload jsonb not null default '{}',idempotency_key text not null,attempts integer not null default 0,max_attempts integer not null default 5,available_at timestamptz not null default now(),locked_at timestamptz,locked_by text,result jsonb,error_message text,created_at timestamptz not null default now(),completed_at timestamptz,unique(organization_id,idempotency_key));
create table public.franchise_finance_audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,profile_id uuid references public.franchise_financial_profiles(id) on delete set null,actor_user_id uuid references auth.users(id),event_type text not null,entity_type text not null,entity_id uuid,reason text,before_state jsonb,after_state jsonb,metadata jsonb not null default '{}',created_at timestamptz not null default now());

create table public.fact_franchise_fee_assessments(assessment_id uuid primary key,organization_id uuid not null,profile_id uuid not null,period_start date not null,fee_type text not null,basis_amount_cents bigint not null,final_amount_cents bigint not null,loaded_at timestamptz not null default now());
create table public.fact_franchise_settlements(settlement_id uuid primary key,organization_id uuid not null,profile_id uuid not null,period_start date not null,status text not null,net_due_cents bigint not null,paid_cents bigint not null default 0,loaded_at timestamptz not null default now());
create table public.fact_franchise_payments(payment_id uuid primary key,organization_id uuid not null,profile_id uuid not null,settlement_id uuid,event_timestamp_utc timestamptz not null,amount_cents bigint not null,status text not null,loaded_at timestamptz not null default now());
create table public.fact_franchise_adjustments(adjustment_id uuid primary key,organization_id uuid not null,profile_id uuid not null,period_start date,adjustment_type text not null,amount_cents bigint not null,status text not null,loaded_at timestamptz not null default now());
create table public.fact_marketing_fund_contributions(contribution_id uuid primary key,organization_id uuid not null,fund_id uuid not null,profile_id uuid not null,period_start date not null,amount_cents bigint not null,status text not null,loaded_at timestamptz not null default now());
create table public.fact_franchise_disputes(dispute_id uuid primary key,organization_id uuid not null,profile_id uuid not null,status text not null,opened_at timestamptz not null,resolved_at timestamptz,loaded_at timestamptz not null default now());
create table public.dim_franchise_fee_type(fee_type text primary key,label text not null);create table public.dim_franchise_profile(profile_id uuid primary key,organization_id uuid not null,store_id uuid not null,brand_id uuid,status text not null,loaded_at timestamptz not null default now());create table public.dim_settlement_status(status text primary key,label text not null);create table public.dim_dispute_status(status text primary key,label text not null);

create index franchise_profile_scope_idx on public.franchise_financial_profiles(organization_id,brand_id,region_id,franchisee_entity_id,status);
create index franchise_rules_effective_idx on public.franchise_fee_rules(organization_id,scope_type,scope_id,effective_from,effective_until) where active;
create index franchise_period_status_idx on public.franchise_assessment_periods(organization_id,status,period_start,period_end);
create index franchise_assessment_period_idx on public.franchise_fee_assessments(assessment_period_id,fee_rule_id);
create index franchise_settlement_due_idx on public.franchise_settlements(organization_id,status,due_date);
create index franchise_ledger_profile_period_idx on public.franchise_financial_ledger(profile_id,period_start,occurred_at,id);
create index franchise_jobs_claim_idx on public.franchise_finance_jobs(status,available_at,created_at) where status in('pending','retrying');
create index franchise_audit_scope_idx on public.franchise_finance_audit_events(organization_id,profile_id,created_at desc);

create or replace function franchise_finance_private.can_access(target_org uuid,target_profile uuid default null,requested_permission text default 'franchise_finance:view') returns boolean language sql stable security definer set search_path='' as $$select (select auth.uid()) is not null and(exists(select 1 from public.organization_members om where om.organization_id=target_org and om.user_id=(select auth.uid()) and om.active and om.role in('owner','admin'))or exists(select 1 from public.franchise_finance_member_permissions p where p.organization_id=target_org and p.user_id=(select auth.uid()) and p.active and(requested_permission=any(p.permissions)or'franchise_finance:view_network'=any(p.permissions))and(target_profile is null or coalesce(array_length(p.store_ids,1),0)=0 or exists(select 1 from public.franchise_financial_profiles fp where fp.id=target_profile and fp.franchisee_entity_id=any(p.store_ids))))or exists(select 1 from public.franchise_financial_profiles fp join public.establishment_members em on em.establishment_id=fp.franchisee_entity_id where fp.id=target_profile and fp.organization_id=target_org and em.user_id=(select auth.uid()) and em.status='active' and(requested_permission in('franchise_finance:view','franchise_finance:view_own'))));$$;
revoke all on function franchise_finance_private.can_access(uuid,uuid,text) from public,anon;grant execute on function franchise_finance_private.can_access(uuid,uuid,text) to authenticated;

do $$declare t text;begin foreach t in array array['franchise_finance_member_permissions','franchise_financial_profiles','fee_basis_policies','franchise_fee_rules','franchise_fee_rule_versions','franchise_fee_tiers','franchise_fee_exemptions','franchise_assessment_periods','franchise_fee_assessments','franchise_adjustments','marketing_fund_accounts','marketing_fund_contributions','marketing_fund_expense_links','franchise_settlements','franchise_statements','franchise_financial_disputes','franchise_financial_ledger','franchise_reconciliation_issues','franchise_finance_jobs','franchise_finance_audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
do $$declare t text;profile_expr text;begin foreach t in array array['franchise_financial_profiles','franchise_fee_rules','franchise_fee_rule_versions','franchise_fee_tiers','franchise_fee_exemptions','franchise_assessment_periods','franchise_fee_assessments','franchise_adjustments','marketing_fund_contributions','franchise_settlements','franchise_statements','franchise_financial_disputes','franchise_financial_ledger','franchise_reconciliation_issues'] loop profile_expr:=case when t='franchise_financial_profiles'then'id' when t='franchise_fee_rules'then'financial_profile_id' when t in('franchise_fee_rule_versions','franchise_fee_tiers')then'(select r.financial_profile_id from public.franchise_fee_rules r where r.id=rule_id)' when t='franchise_fee_assessments'then'(select p.profile_id from public.franchise_assessment_periods p where p.id=assessment_period_id)' else'profile_id'end;execute format('grant select on public.%I to authenticated',t);execute format('create policy %I on public.%I for select to authenticated using((select franchise_finance_private.can_access(organization_id,%s,''franchise_finance:view'')))','franchise_finance_read_'||t,t,profile_expr);end loop;end$$;
do $$declare t text;begin foreach t in array array['franchise_finance_member_permissions','fee_basis_policies','marketing_fund_accounts','marketing_fund_expense_links','franchise_finance_jobs','franchise_finance_audit_events'] loop execute format('create policy %I on public.%I for all to service_role using(true) with check(true)','franchise_finance_service_'||t,t);end loop;end$$;
do $$declare t text;begin foreach t in array array['franchise_financial_profiles','franchise_fee_rules','franchise_fee_rule_versions','franchise_fee_tiers','franchise_fee_exemptions','franchise_assessment_periods','franchise_fee_assessments','franchise_adjustments','marketing_fund_contributions','franchise_settlements','franchise_statements','franchise_financial_disputes','franchise_financial_ledger','franchise_reconciliation_issues'] loop execute format('create policy %I on public.%I for all to service_role using(true) with check(true)','franchise_finance_service_'||t,t);end loop;end$$;

-- Warehouse facts and dimensions are populated by trusted jobs and consumed through
-- governed analytics datasets. They are not directly exposed through the Data API.
do $$declare t text;begin foreach t in array array['fact_franchise_fee_assessments','fact_franchise_settlements','fact_franchise_payments','fact_franchise_adjustments','fact_marketing_fund_contributions','fact_franchise_disputes','dim_franchise_fee_type','dim_franchise_profile','dim_settlement_status','dim_dispute_status'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant all on public.%I to service_role',t);execute format('create policy %I on public.%I for all to service_role using(true) with check(true)','franchise_finance_service_'||t,t);end loop;end$$;

create or replace function franchise_finance_private.prevent_financial_mutation()returns trigger language plpgsql set search_path='' as $$begin raise exception 'append-only financial record';end$$;revoke all on function franchise_finance_private.prevent_financial_mutation()from public,anon,authenticated;
create trigger franchise_ledger_immutable before update or delete on public.franchise_financial_ledger for each row execute function franchise_finance_private.prevent_financial_mutation();
create trigger franchise_rule_versions_immutable before update or delete on public.franchise_fee_rule_versions for each row execute function franchise_finance_private.prevent_financial_mutation();

create or replace function public.claim_franchise_finance_jobs(requested_worker text,requested_limit integer default 10)returns setof public.franchise_finance_jobs language plpgsql security definer set search_path='' as $$begin return query update public.franchise_finance_jobs j set status='processing',locked_at=now(),locked_by=requested_worker,attempts=j.attempts+1 where j.id in(select id from public.franchise_finance_jobs where status in('pending','retrying')and available_at<=now()order by created_at limit least(greatest(requested_limit,1),50)for update skip locked)returning j.*;end$$;revoke all on function public.claim_franchise_finance_jobs(text,integer)from public,anon,authenticated;grant execute on function public.claim_franchise_finance_jobs(text,integer)to service_role;

alter table public.financial_entries drop constraint if exists financial_entries_source_type_check;
alter table public.financial_entries add constraint financial_entries_source_type_check check(source_type in('order','purchase_order','supplier_invoice','subscription','gateway_fee','refund','manual','payroll_summary','franchise_settlement','other'));
alter table public.store_feature_flags add column if not exists franchise_finance_enabled boolean not null default false,add column if not exists franchise_royalties_enabled boolean not null default false,add column if not exists marketing_fund_enabled boolean not null default false,add column if not exists franchise_settlements_enabled boolean not null default false,add column if not exists franchise_finance_forecast_enabled boolean not null default false;
alter table public.plans add column if not exists franchise_finance_enabled boolean not null default false,add column if not exists franchise_royalties_enabled boolean not null default false,add column if not exists marketing_fund_enabled boolean not null default false,add column if not exists franchise_settlements_enabled boolean not null default false,add column if not exists franchise_finance_forecast_enabled boolean not null default false;

insert into public.automation_event_registry(event_name,module,description,payload_schema,allowed_fields,sensitivity)values('franchise.period_ready','franchise_finance','Período pronto para revisão.','{"type":"object"}',array['organization.id','profile.id','period.id'],'restricted'),('franchise.assessment_approved','franchise_finance','Avaliação financeira aprovada.','{"type":"object"}',array['profile.id','assessment.id','assessment.amount'],'restricted'),('franchise.settlement_issued','franchise_finance','Cobrança gerencial emitida.','{"type":"object"}',array['profile.id','settlement.id','settlement.amount'],'restricted'),('franchise.settlement_overdue','franchise_finance','Cobrança de franquia vencida.','{"type":"object"}',array['profile.id','settlement.id','settlement.due_date'],'restricted'),('franchise.payment_received','franchise_finance','Pagamento recebido e conciliado.','{"type":"object"}',array['profile.id','settlement.id','payment.amount'],'restricted'),('franchise.dispute_opened','franchise_finance','Contestação financeira aberta.','{"type":"object"}',array['profile.id','dispute.id'],'restricted')on conflict(event_name,schema_version)do update set description=excluded.description,active=true;
