insert into public.analytics_datasets(dataset_key,name,description,domain,owner_label,dataset_scope,grain,source_tables,refresh_frequency,retention_days,certified,contains_pii)values('franchise_fee_assessments','Franchise Fee Assessments','Avaliações de taxas por período.','franchise_finance','Financeiro da Rede','customer_analytics','perfil/regra/período',array['franchise_fee_assessments'],'hourly',2555,true,false),('franchise_settlements','Franchise Settlements','Cobranças e recebimentos.','franchise_finance','Financeiro da Rede','customer_analytics','perfil/período',array['franchise_settlements','financial_entries'],'hourly',2555,true,false),('franchise_marketing_funds','Franchise Marketing Funds','Contribuições e despesas vinculadas.','franchise_finance','Financeiro da Rede','customer_analytics','fundo/período',array['marketing_fund_contributions','marketing_fund_expense_links'],'hourly',2555,true,false),('franchise_reconciliation','Franchise Reconciliation','Divergências da conciliação especializada.','franchise_finance','Financeiro da Rede','customer_analytics','settlement/payment',array['franchise_reconciliation_issues','financial_reconciliations'],'hourly',2555,true,false),('franchise_disputes','Franchise Disputes','Contestações financeiras.','franchise_finance','Financeiro da Rede','customer_analytics','disputa',array['franchise_financial_disputes'],'hourly',2555,true,false)on conflict(dataset_key)do update set description=excluded.description,source_tables=excluded.source_tables,certified=true;
insert into public.analytics_metric_catalog(metric_key,name,description,formula,source_of_truth,grain,owner_label,refresh_frequency,unit,evidence_class,certified,sensitive,allowed_dimensions)values('royalty_assessed','Royalty Assessed','Royalty aprovado no período.','sum(final_amount_cents) where fee_type=royalty','franchise_fee_assessments','organization/profile/period','Financeiro da Rede','hourly','BRL','fact',true,true,array['organization','brand','region','store','period']),('royalty_collected','Royalty Collected','Royalty conciliado e recebido.','sum(payment amount linked to royalty settlement)','financial_entry_payments','organization/profile/period','Financeiro da Rede','hourly','BRL','fact',true,true,array['organization','brand','region','store','period']),('royalty_collection_rate','Royalty Collection Rate','Royalty recebido dividido por royalty vencido elegível.','royalty_collected / nullif(royalty_due,0)','franchise settlements semantic view','organization/period','Financeiro da Rede','hourly','percent','calculation',true,true,array['organization','brand','region','period']),('marketing_fund_assessed','Marketing Fund Assessed','Contribuições avaliadas.','sum(marketing contribution amount)','marketing_fund_contributions','fund/period','Financeiro da Rede','hourly','BRL','fact',true,true,array['organization','brand','region','period']),('outstanding_franchise_fees','Outstanding Franchise Fees','Saldo em aberto de taxas.','sum(net_due-paid)','franchise_settlements + financial_entries','profile/period','Financeiro da Rede','hourly','BRL','calculation',true,true,array['organization','brand','region','store','period']),('overdue_franchise_fees','Overdue Franchise Fees','Saldo vencido sem consequência jurídica automática.','sum(outstanding where due_date<today)','franchise_settlements','profile/period','Financeiro da Rede','hourly','BRL','calculation',true,true,array['organization','brand','region','store','aging']),('average_days_to_collection','Average Days to Collection','Média entre emissão e liquidação.','avg(settled_at-created_at)','franchise_settlements','organization/period','Financeiro da Rede','daily','days','calculation',true,true,array['organization','brand','region','period']),('franchise_close_completion_rate','Franchise Close Completion Rate','Períodos fechados sobre elegíveis.','closed periods / eligible periods','franchise_assessment_periods','organization/period','Financeiro da Rede','hourly','percent','calculation',true,false,array['organization','brand','region','period']),('franchise_dispute_rate','Franchise Dispute Rate','Disputas sobre settlements emitidos.','disputes / issued settlements','franchise_financial_disputes','organization/period','Financeiro da Rede','daily','percent','calculation',true,true,array['organization','brand','region','period']),('projected_royalty_revenue','Projected Royalty Revenue','Projeção não reconhecida de royalties.','forecast basis × effective rule','forecast_predictions + franchise_fee_rules','organization/profile/period','Financeiro da Rede','hourly','BRL','estimate',true,true,array['organization','brand','region','store','period'])on conflict(metric_key)do update set description=excluded.description,formula=excluded.formula,source_of_truth=excluded.source_of_truth,sensitive=excluded.sensitive;
